<?php
require_once __DIR__.'/../includes/db_connect.php';require_once __DIR__.'/../includes/auth.php';requireRole('instructor');
$st=$pdo->prepare("SELECT a.attempt_id,a.score,a.attempt_number,a.is_final,a.submitted_at,q.title,q.created_by_instructor_id,c.course_name,u.name,u.surname,u.email FROM quiz_attempts a JOIN quizzes q ON q.quiz_id=a.quiz_id JOIN courses c ON c.course_id=q.course_id JOIN users u ON u.user_id=a.user_id WHERE EXISTS (SELECT 1 FROM course_assignments ca WHERE ca.course_id=c.course_id AND ca.instructor_id=?) ORDER BY a.submitted_at DESC");$st->execute([$_SESSION['user_id']]);$results=$st->fetchAll();$pageTitle='Quiz Results';require __DIR__.'/../includes/header.php';
?><div class="page-heading"><div><div class="eyebrow">INSTRUCTOR PORTAL</div><h1>Quiz Results</h1><p>Review learner performance in your assigned courses.</p></div></div><section class="dashboard-card"><div class="table-container"><table><thead><tr><th>Learner</th><th>Quiz</th><th>Course</th><th>Attempt</th><th>Score</th><th>Result</th><th>Submitted</th><th>Action</th></tr></thead><tbody><?php if(!$results):?><tr><td colspan="8">No quiz attempts yet.</td></tr><?php else:foreach($results as $r):?><tr><td><?=e($r['name'].' '.$r['surname'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['title'])?></td><td><?=e($r['course_name'])?></td><td><?=e($r['attempt_number'])?></td><td><strong><?=e($r['score'])?>%</strong></td><td><?= (int)$r['is_final']===1 ? '<span class="badge badge-learner">Final</span>' : '<span class="badge badge-admin">Superseded</span>' ?></td><td><?=e($r['submitted_at'])?></td><td><?php if((int)$r['created_by_instructor_id']===(int)$_SESSION['user_id']):?><a class="btn btn-outline btn-small" href="../learner/quiz_review.php?attempt_id=<?=(int)$r['attempt_id']?>">Review</a><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
